// Generated by OSL (@osl/backend-hono-trpc-vite). The tenant context: the team the sidebar's switcher chose, for the pages that filter by it.
// Do not edit: this file is rewritten on every osl generate.

"use client";
import { useQuery } from "@tanstack/react-query";
import { Link } from "@tanstack/react-router";
import { useSyncExternalStore } from "react";
import { cn } from "@/lib/utils";
import { client, sessionUser, type Outputs } from "./client";
import { EmptyPane, selectClass, text } from "./ui";

/** A team the signed-in user can work in: a row the teams resource lists for them */
export type Tenant = Outputs["teams"]["list"]["data"][number];

const STORAGE_KEY = "osl.tenant";
const LIST = { page_size: 200 };
const NONE: readonly Tenant[] = [];

/** The chosen key; undefined until the browser's storage has been read */
let chosen: string | null | undefined;
const listeners = new Set<() => void>();

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** The remembered choice: this tab's, else the last one made in any tab */
function readChoice(): string | null {
  if (chosen !== undefined) return chosen;
  chosen = null;
  try {
    chosen = window.sessionStorage.getItem(STORAGE_KEY) ?? window.localStorage.getItem(STORAGE_KEY);
    if (chosen !== null) window.sessionStorage.setItem(STORAGE_KEY, chosen);
  } catch {
    // Storage is blocked: the choice lasts until the page reloads
  }
  return chosen;
}

function writeChoice(key: string): void {
  chosen = key;
  try {
    window.sessionStorage.setItem(STORAGE_KEY, key);
    window.localStorage.setItem(STORAGE_KEY, key);
  } catch {
    // Storage is blocked: the choice lasts until the page reloads
  }
  for (const listener of listeners) listener();
}

/**
 * The team in context, the ones the user can change to, and the setter. A remembered team the user is
 * no longer in falls back to the first one listed; tenant is null while loading and for a user who is in none.
 */
export function useTenant(): {
  tenant: Tenant | null;
  tenants: readonly Tenant[];
  setTenant: (key: string) => void;
  loading: boolean;
} {
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  const list = useQuery({
    queryKey: ["teams", "list", LIST],
    queryFn: () => client.teams.list(LIST),
    enabled: user !== null
  });
  const choice = useSyncExternalStore(subscribe, readChoice, () => null);
  const tenants = user !== null ? (list.data?.data ?? NONE) : NONE;
  const current = tenants.find(item => text(item.id) === choice) ?? tenants[0] ?? null;
  return {
    tenant: current,
    tenants,
    setTenant: writeChoice,
    loading: session.isPending || (user !== null && list.isPending)
  };
}

/** Makes a team the current one when the signed-in user is in it; otherwise the choice stays where it was */
export async function chooseTenant(key: string): Promise<void> {
  const list = await client.teams.list(LIST);
  if (list.data.some(item => text(item.id) === key)) writeChoice(key);
}

/** The switcher the sidebar shows in its header: the current team, and the ones the user can change to */
export function TenantSwitcher({ className }: { className?: string }) {
  const { tenant, tenants, setTenant } = useTenant();
  if (tenant === null) return null;
  return (
    <select
      aria-label="Team"
      className={cn(selectClass, "group-data-[collapsible=icon]:hidden", className)}
      value={text(tenant.id)}
      onChange={event => setTenant(event.target.value)}
    >
      {tenants.map(item => (
        <option key={text(item.id)} value={text(item.id)}>
          {text(item.name) || text(item.id)}
        </option>
      ))}
    </select>
  );
}

/** What a page filtered by the team shows to a user who is in none */
export function NoTenant() {
  return (
    <EmptyPane>
      <div className="space-y-2">
        <p>You are not in any team yet.</p>
        <Link to="/teams" className="text-foreground underline underline-offset-4">
          Open Teams
        </Link>
      </div>
    </EmptyPane>
  );
}
